class QueryResults[T]:
    """Helper class that allows both iteration and normal fetching of data from the db."""

    __slots__ = ("_args", "_conn", "_cursor", "_decode_hook", "_sql")

    def __init__(
        self,
        conn: turso.Connection,
        sql: str,
        decode_hook: collections.abc.Callable[[tuple[typing.Any, ...]], T],
        *args: QueryResultsArgsType,
    ) -> None:
        """Initialize the QueryResults instance.

        Arguments:
        conn -- The connection object of type `turso.Connection` used to execute queries.
        sql -- The SQL statement that will be executed when fetching/iterating.
        decode_hook -- A callback that turns an `tuple[typing.Any, ...]` object into `T` that will be returned.
        *args -- Arguments that should be sent when executing the sql query.
        """
        self._conn = conn
        self._sql = sql
        self._decode_hook = decode_hook
        self._args = args
        self._cursor: turso.Cursor | None = None

    def __iter__(self) -> QueryResults[T]:
        """Initialize iteration support.

        Returns:
        Self as an iterator.
        """
        return self

    def __call__(
        self,
    ) -> collections.abc.Sequence[T]:
        """Allow calling the object to return all rows as a fully decoded sequence.

        Returns:
        A sequence of decoded objects of type `T`.
        """
        result = self._conn.execute(self._sql, self._args).fetchall()
        return [self._decode_hook(row) for row in result]

    def __next__(self) -> T:
        """Yield the next item in the query result using a turso cursor.

        Returns:
        The next decoded result of type `T`.

        Raises:
        StopIteration -- When no more records are available.
        """
        if self._cursor is None:
            self._cursor = self._conn.execute(self._sql, self._args)
        record = self._cursor.fetchone()
        if record is None:
            self._cursor = None
            raise StopIteration
        return self._decode_hook(record)


